package com.factory.copilot.controller; import com.factory.copilot.service.CopilotService; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestController @RequestMapping("/api/copilot") @CrossOrigin(origins = "*") public class CopilotController { private final CopilotService copilotService; public CopilotController(CopilotService copilotService) { this.copilotService = copilotService; } @GetMapping("/machine/{machineId}") public Map<String,Object> getMachineContext(@PathVariable Long machineId) { return copilotService.getMachineContext(machineId); } }
